# frozen_string_literal: true

# Homebrew cask for Emergic.app. Generated by `scripts/package-emergic.sh VERSION` in
# atrium-solutions/emergic-app (private) from that release's SHA256SUMS — edit the template in
# packaging/brew/, not this file.
#
# Apple Silicon only: the bundled llama-server is built for arm64 with Metal. The app is
# ad-hoc signed, not notarised, so the postflight clears the download quarantine and the
# caveats say so.
cask "emergic" do
  version "0.2.0"
  sha256 "fd32d8d7ec384fb3e751d39c53e127dd46e9e0e338eb101e7dc15df1bbdfc1ba"

  url "https://github.com/atrium-solutions/emergic-releases/releases/download/v0.2.0/Emergic-macos.zip"
  name "Emergic"
  desc "Office AI chat served by your office's own idle computers"
  homepage "https://github.com/atrium-solutions/emergic-releases"

  livecheck do
    url :url
    strategy :github_latest
  end

  depends_on arch: :arm64

  # Emergic updates itself from the office server once the admin approves a release, so
  # `brew upgrade` leaves it alone (`brew upgrade --greedy` still updates it).
  auto_updates true

  app "Emergic.app"

  postflight_steps do
    run "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "{{appdir}}/Emergic.app"]
  end

  # The ai.otium.* entries are what Otium 0.1.x left; Emergic 0.2.0 removes them at its
  # first start, so they are here only for a Mac that never started it.
  uninstall launchctl: ["com.emergic.app", "com.emergic.check", "ai.otium.app", "ai.otium.check"],
            quit:      "com.emergic.app",
            trash:     [
              "~/Library/LaunchAgents/com.emergic.check.plist",
              "~/Library/LaunchAgents/ai.otium.check.plist",
            ]

  zap trash: [
    "~/.emergic",
    "~/Library/Application Support/com.emergic.app",
    "~/Library/Application Support/Emergic",
    "~/Library/Caches/com.emergic.app",
    "~/Library/LaunchAgents/com.emergic.app.plist",
    "~/Library/Logs/com.emergic.app",
    "~/Library/WebKit/com.emergic.app",
    "~/.otium",
    "~/Library/Application Support/ai.otium.app",
    "~/Library/Application Support/Otium",
    "~/Library/Caches/ai.otium.app",
    "~/Library/LaunchAgents/ai.otium.app.plist",
    "~/Library/Logs/ai.otium.app",
    "~/Library/WebKit/ai.otium.app",
  ]

  caveats <<~EOS
    Emergic #{version} is not Apple-notarised; macOS cannot name the developer. If it is
    still blocked, open it once with right-click → Open, or run:
      xattr -dr com.apple.quarantine "#{appdir}/Emergic.app"

    On first launch, choose: join your office, run the office server, or just chat.
    On the office server, Emergic installs and runs web search (SearXNG) itself on first
    start (about a minute; it needs the internet once). No container is needed.
    `brew uninstall --zap --cask emergic` also removes the office data on this Mac,
    including an office server's certificate authority — back it up first.
  EOS
end
